#!/usr/bin/env python3
# gen_prelude.py -- write src/radtypes.h, the fixed-width type prelude used by
# every recovered translation unit (see CONVENTIONS.md, "Type system").
#
# The output is intentionally tiny and stable: it defines u8/u16/u32, their
# signed counterparts and the word16/word32/byte aliases.  See README.md.

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import reko_common as rc  # noqa: E402

TEMPLATE = """#ifndef RADTYPES_H
#define RADTYPES_H

/* Fixed-width types for the RAD V3.1 preservation port.
 * Generated by analysis/tools/gen_prelude.py -- do not edit by hand.
 * See CONVENTIONS.md (Type system): u8/u16/u32/s8/s16/s32 plus the
 * word16/word32/byte aliases used by the Reko output. */

typedef unsigned char      u8;
typedef unsigned short     u16;
typedef unsigned int      u32;
typedef signed char        s8;
typedef signed short       s16;
typedef signed int        s32;

typedef u16 word16;
typedef u32 word32;
typedef u8  byte;

#endif /* RADTYPES_H */
"""


def main():
    rc.ensure_dir(rc.SRC_DIR)
    out_path = os.path.join(rc.SRC_DIR, "radtypes.h")
    with open(out_path, "w", encoding="utf-8") as fh:
        fh.write(TEMPLATE)
    print("wrote %s" % out_path)


if __name__ == "__main__":
    main()
